after.content:
$privateBundleDirectory = Join-Path $artifacts 'private-host'
New-Item -ItemType Directory -Force -Path $privateBundleDirectory | Out-Null
foreach ($name in @('ji-host-linux-amd64-java21.tar.gz','ji-host-linux-amd64-java21.manifest.json','ji-host-linux-amd64-java21.public.pem')) {
    $source = Join-Path $ubuntuArtifacts $name
    if (-not (Test-Path -LiteralPath $source -PathType Leaf)) { throw "private Host bundle input is unavailable: $name" }
    Copy-Item -LiteralPath $source -Destination (Join-Path $privateBundleDirectory $name)
}

Invoke-Checked { node "$repo\scripts\generate-sbom.mjs" $output $artifacts } 'CycloneDX and SPDX SBOM'
Invoke-Checked { node "$repo\scripts\generate-provenance.mjs" $output $artifacts } 'build provenance'
